-- EzWoW_MapFinder: Additional Monster Locations Database (Names + Multi-Spawn Coordinates)
EzWoWMapFinderData = EzWoWMapFinderData or {}
EzWoWMapFinderTranslations = EzWoWMapFinderTranslations or {}
EzWoWMapFinderTranslations.koKR = EzWoWMapFinderTranslations.koKR or {}
EzWoWMapFinderTranslations.koKR.npc = EzWoWMapFinderTranslations.koKR.npc or {}
EzWoWMapFinderTranslations.koKR.subname = EzWoWMapFinderTranslations.koKR.subname or {}

local byId = {}
local byEnName = {}
for _, e in ipairs(EzWoWMapFinderData) do
  if e.kind == 'npc' then
    if e.id then byId[e.id] = e end
    if e.names and e.names.enUS then byEnName[e.names.enUS] = e end
  end
end

local function regMonster(id, enName, koName, subName, zoneStr, spawns, alias)
  if koName and koName ~= '' then
    EzWoWMapFinderTranslations.koKR.npc[id] = EzWoWMapFinderTranslations.koKR.npc[id] or koName
  end
  if subName and subName ~= '' then
    EzWoWMapFinderTranslations.koKR.subname[id] = EzWoWMapFinderTranslations.koKR.subname[id] or subName
  end
  local e = byId[id] or (enName and byEnName[enName])
  if not e then
    e = { id = id, kind = 'npc', names = { enUS = enName, koKR = koName }, flags = 0, spawns = spawns or {} }
    EzWoWMapFinderData[#EzWoWMapFinderData + 1] = e
    byId[id] = e
  else
    e.id = e.id or id
    byId[id] = e
    e.names = e.names or {}
    e.names.enUS = e.names.enUS or enName
    if koName and koName ~= '' then e.names.koKR = e.names.koKR or koName end
    if spawns and #spawns > 0 and (not e.spawns or #spawns > #e.spawns) then
      e.spawns = spawns
    end
  end
  e.isMonster = true
  e.isRare = true
  if zoneStr and zoneStr ~= '' then e.zone = zoneStr end
  if alias and alias ~= '' then
    e.aliases = e.aliases or {}
    e.aliases[#e.aliases + 1] = alias
  end
end

